static NSMutableDictionary *BrowserSessions(void){static NSMutableDictionary *sessions;static dispatch_once_t once;dispatch_once(&once,^{sessions=[NSMutableDictionary new];});return sessions;}
static NSString *BrowserPreference(NSString *session){return [@"DylixBrowserPersist-" stringByAppendingString:[TFAIAgentContext fingerprint:session?:@"settings"]];}
static WKWebsiteDataStore *SessionStore(NSString *session){if(@available(iOS 17.0,*)){if([NSUserDefaults.standardUserDefaults boolForKey:BrowserPreference(session)]){NSString *hash=[TFAIAgentContext fingerprint:session?:@"settings"];NSString *uuid=[NSString stringWithFormat:@"%@-%@-%@-%@-%@",[hash substringToIndex:8],[hash substringWithRange:NSMakeRange(8,4)],[hash substringWithRange:NSMakeRange(12,4)],[hash substringWithRange:NSMakeRange(16,4)],[hash substringWithRange:NSMakeRange(20,12)]];return [WKWebsiteDataStore dataStoreForIdentifier:[[NSUUID alloc]initWithUUIDString:uuid]];}}return WKWebsiteDataStore.nonPersistentDataStore;}
static void BrowserChanged(NSString *session){dispatch_async(dispatch_get_main_queue(),^{[NSNotificationCenter.defaultCenter postNotificationName:@"DylixBrowserTabChanged" object:session?:@"settings"];});}
static NSMutableDictionary *BrowserState(NSString *session){NSString *key=session.length?session:@"settings";NSMutableDictionary *state=BrowserSessions()[key];if(!state){if(BrowserSessions().count>=16)return nil;state=[@{@"tabs":[NSMutableArray new],@"active":@""} mutableCopy];BrowserSessions()[key]=state;}return state;}
+ (instancetype)browserForSession:(NSString *)sessionID{NSAssert(NSThread.isMainThread,@"Browser UI must run on main queue");NSMutableDictionary *state=BrowserState(sessionID);if(![state[@"tabs"] count])[self newTabForSession:sessionID];for(NSDictionary *tab in state[@"tabs"])if([tab[@"id"] isEqual:state[@"active"]])return tab[@"browser"];return nil;}
+ (BOOL)AIBlockedForSession:(NSString *)session{NSDictionary *state=BrowserState(session);return !state||[state[@"manual"] boolValue]||[state[@"clearing"] boolValue];}
+ (BOOL)setManualLogin:(BOOL)manual session:(NSString *)session{NSMutableDictionary *state=BrowserState(session);if(!state||[state[@"clearing"] boolValue])return NO;NSArray *tabs=[state[@"tabs"] copy];for(NSDictionary *tab in tabs)[tab[@"browser"] cancel];state[@"manual"]=@(manual);NSMutableArray *next=[NSMutableArray new];for(NSDictionary *tab in tabs){TFAIReadOnlyBrowser *old=tab[@"browser"];TFAIReadOnlyBrowser *replacement=[[self alloc]initWithSession:session manual:manual&&[state[@"active"] isEqual:tab[@"id"]] store:old.webView.configuration.websiteDataStore];[next addObject:@{@"id":tab[@"id"],@"browser":replacement}];if(old.webView.URL)[replacement.webView loadRequest:[NSURLRequest requestWithURL:old.webView.URL]];}state[@"tabs"]=next;BrowserChanged(session);return YES;}
+ (BOOL)newTabForSession:(NSString *)session{NSMutableDictionary *state=BrowserState(session);NSMutableArray *tabs=state[@"tabs"];if(!tabs||tabs.count>=8||[state[@"manual"] boolValue]||[state[@"clearing"] boolValue])return NO;NSString *identifier=NSUUID.UUID.UUIDString;[tabs addObject:@{@"id":identifier,@"browser":[[self alloc]initWithSession:session manual:NO store:nil]}];state[@"active"]=identifier;BrowserChanged(session);return YES;}
+ (NSArray *)tabsForSession:(NSString *)session{NSMutableDictionary *state=BrowserState(session);NSMutableArray *out=[NSMutableArray new];for(NSDictionary *tab in state[@"tabs"]){TFAIReadOnlyBrowser *browser=tab[@"browser"];[out addObject:@{@"id":tab[@"id"],@"title":browser.webView.title?:@"新标签",@"url":browser.webView.URL.absoluteString?:@"",@"active":@([state[@"active"] isEqual:tab[@"id"]])}];}return out;}
+ (BOOL)selectTab:(NSString *)identifier session:(NSString *)session{NSMutableDictionary *state=BrowserState(session);if([self AIBlockedForSession:session])return NO;for(NSDictionary *tab in state[@"tabs"])if([tab[@"id"] isEqual:identifier]){state[@"active"]=identifier;BrowserChanged(session);return YES;}return NO;}
+ (void)closeTab:(NSString *)identifier session:(NSString *)session{NSMutableDictionary *state=BrowserState(session);NSMutableArray *tabs=state[@"tabs"];if([self AIBlockedForSession:session])return;for(NSDictionary *tab in [tabs copy])if([tab[@"id"] isEqual:identifier]){[tab[@"browser"] cancel];[tabs removeObject:tab];break;}if([state[@"active"] isEqual:identifier])state[@"active"]=[tabs.firstObject objectForKey:@"id"]?:@"";if(!tabs.count)[self newTabForSession:session];BrowserChanged(session);}
+ (void)clearSession:(NSString *)session completion:(dispatch_block_t)completion{NSMutableDictionary *state=BrowserState(session);if([state[@"clearing"] boolValue]){if(completion)completion();return;}state[@"clearing"]=@YES;NSArray *tabs=[state[@"tabs"] copy];dispatch_group_t group=dispatch_group_create();for(NSDictionary *tab in tabs){TFAIReadOnlyBrowser *browser=tab[@"browser"];[browser cancel];dispatch_group_enter(group);[browser.webView.configuration.websiteDataStore removeDataOfTypes:WKWebsiteDataStore.allWebsiteDataTypes modifiedSince:NSDate.distantPast completionHandler:^{dispatch_group_leave(group);}];}dispatch_group_notify(group,dispatch_get_main_queue(),^{[state[@"tabs"] removeAllObjects];state[@"active"]=@"";state[@"manual"]=@NO;state[@"clearing"]=@NO;[self newTabForSession:session];if(completion)completion();});}
- (instancetype)init{return [self initWithSession:nil manual:NO store:nil];}
- (instancetype)initWithSession:(NSString *)session manual:(BOOL)manual store:(WKWebsiteDataStore *)store{if((self=[super init])){self.manualLogin=manual;self.ownerSession=session;WKWebViewConfiguration *c=[WKWebViewConfiguration new];c.websiteDataStore=store?:SessionStore(session);c.preferences.javaScriptCanOpenWindowsAutomatically=NO;NSString *guard=@"(()=>{const f=window.fetch;window.fetch=(u,o={})=>{if(!['GET','HEAD'].includes((o.method||u?.method||'GET').toUpperCase()))return Promise.reject(Error('Dylix read-only browser'));return f(u,o)};const op=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,...a){if(!['GET','HEAD'].includes(String(m).toUpperCase()))throw Error('Dylix read-only browser');return op.call(this,m,...a)};document.addEventListener('submit',e=>{const f=e.target;if((f.method||'get').toLowerCase()!='get'||f.querySelector('input[type=password],input[type=file]')){e.preventDefault();e.stopImmediatePropagation()}},true);const disable=()=>document.querySelectorAll('input[type=password],input[type=file],[contenteditable]').forEach(n=>{n.setAttribute('disabled','disabled');n.setAttribute('contenteditable','false')});document.addEventListener('DOMContentLoaded',disable);new MutationObserver(disable).observe(document,{subtree:true,childList:true});navigator.sendBeacon=()=>false;})()";if(!manual)[c.userContentController addUserScript:[[WKUserScript alloc]initWithSource:guard injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:NO]];_webView=[[WKWebView alloc]initWithFrame:CGRectMake(0,0,800,1000) configuration:c];_webView.navigationDelegate=self;_webView.UIDelegate=self;_webView.allowsLinkPreview=NO;__weak typeof(self) weak=self;_interaction=[[TFAIWebDOM alloc]initWithWebView:_webView validator:^BOOL(NSURL *u){return weak&&![TFAIReadOnlyBrowser AIBlockedForSession:weak.ownerSession]&&!weak.manualLogin&&[TFAIToolRegistry enabled:@"browser"]&&TFAIWebTools.enabled&&UIApplication.sharedApplication.applicationState==UIApplicationStateActive&&[TFAIWebTools validURL:u error:nil];}];}return self;}
- (void)finish:(NSDictionary *)result error:(NSError *)error{TFAIResult c=self.completion;self.completion=nil;[self.webView stopLoading];self.activeNavigation=nil;if(c)c(result,error);}
- (void)cancel{self.serial++;[self finish:nil error:TFAIError(NSURLErrorCancelled,@"只读浏览已停止。")];}
- (void)read:(NSString *)url completion:(TFAIResult)completion{if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{[self read:url completion:completion];});return;}[self cancel];if(self.manualLogin||[TFAIReadOnlyBrowser AIBlockedForSession:self.ownerSession]){completion(nil,TFAIError(480,@"手动登录期间 AI 网页工具已停用，请在浏览器完成或退出手动登录。"));return;}if(![TFAIToolRegistry enabled:@"browser"]||!TFAIWebTools.enabled||UIApplication.sharedApplication.applicationState!=UIApplicationStateActive){completion(nil,TFAIError(480,@"浏览器已关闭或应用不在前台。"));return;}NSError *error=nil;NSURL *target=url.length?[NSURL URLWithString:url]:self.webView.URL;if(![TFAIWebTools validURL:target error:&error]){completion(nil,error?:TFAIError(480,@"请先打开公开 HTTPS 网页。"));return;}self.completion=completion;self.lastText=nil;self.attempts=0;NSUInteger serial=++self.serial;if(self.webView.URL&&[self.webView.URL.absoluteString isEqual:target.absoluteString]&&!self.webView.isLoading){[self extract:serial final:NO];}else self.activeNavigation=[self.webView loadRequest:[NSURLRequest requestWithURL:target]];dispatch_after(dispatch_time(DISPATCH_TIME_NOW,20*NSEC_PER_SEC),dispatch_get_main_queue(),^{if(serial==self.serial&&self.completion)[self extract:serial final:YES];});}
- (void)perform:(NSDictionary *)arguments completion:(TFAIResult)completion{
 if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{[self perform:arguments completion:completion];});return;}
 if(self.manualLogin||[TFAIReadOnlyBrowser AIBlockedForSession:self.ownerSession]){completion(nil,TFAIError(480,@"手动登录期间 AI 网页工具已停用。"));return;}
 NSString *action=[arguments[@"action"] isKindOfClass:NSString.class]?arguments[@"action"]:(arguments[@"url"]?@"navigate":@"current");
 if([action isEqual:@"navigate"]){NSString *url=arguments[@"url"];if(!url.length){completion(nil,TFAIError(480,@"打开网页需要 URL。"));return;}[self read:url completion:completion];return;}
 if([action isEqual:@"current"]){[self read:nil completion:completion];return;}
 if(![TFAIToolRegistry enabled:@"browser"]||!TFAIWebTools.enabled||UIApplication.sharedApplication.applicationState!=UIApplicationStateActive){completion(nil,TFAIError(480,@"浏览器已关闭或应用不在前台。"));return;}
 NSError *error=nil;if(![TFAIWebTools validURL:self.webView.URL error:&error]){completion(nil,error?:TFAIError(480,@"请先打开公开 HTTPS 网页。"));return;}
 if([@[@"observe",@"click",@"type",@"select",@"screenshot"] containsObject:action]){[self.interaction perform:arguments completion:completion];return;}
 if([action isEqual:@"back"]||[action isEqual:@"forward"]){
  BOOL back=[action isEqual:@"back"];if(back?!self.webView.canGoBack:!self.webView.canGoForward){completion(nil,TFAIError(480,@"浏览历史中没有对应页面。"));return;}
  [self cancel];self.completion=completion;self.lastText=nil;self.attempts=0;NSUInteger serial=++self.serial;self.activeNavigation=back?[self.webView goBack]:[self.webView goForward];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW,20*NSEC_PER_SEC),dispatch_get_main_queue(),^{if(serial==self.serial&&self.completion)[self extract:serial final:YES];});return;
 }
 if([action isEqual:@"follow_link"]){
  NSNumber *index=arguments[@"link_index"];if(![index isKindOfClass:NSNumber.class]||index.integerValue<0||index.integerValue>=100){completion(nil,TFAIError(480,@"请指定页面返回的链接序号 0–99。"));return;}
  NSString *js=[NSString stringWithFormat:@"(()=>{const root=document.querySelector('main,article,[role=main]')||document.body;return Array.from(root?.querySelectorAll('a[href]')||[]).filter(a=>/^https?:/.test(a.href)).slice(0,100)[%ld]?.href||''})()",(long)index.integerValue];
  [self.webView evaluateJavaScript:js completionHandler:^(id value,NSError *failure){if(failure||![value isKindOfClass:NSString.class]||![value length]){completion(nil,TFAIError(480,@"链接已变化，请重新读取当前页。"));return;}[self read:value completion:completion];}];return;
 }
 if([action isEqual:@"scroll"]){
  NSString *direction=[arguments[@"direction"] isEqual:@"up"]?@"up":@"down";NSInteger amount=arguments[@"amount"]?[arguments[@"amount"] integerValue]:1;amount=MAX(1,MIN(5,amount));
