 }
 completion(nil,TFAIError(480,@"不支持此浏览操作。"));
}
- (void)webView:(WKWebView *)webView decidePolicyForNavigationAction:(WKNavigationAction *)action decisionHandler:(void (^)(WKNavigationActionPolicy))handler{if(action.targetFrame.isMainFrame)[self.interaction invalidate];NSError *error=nil;BOOL valid=(self.manualLogin||[action.request.HTTPMethod isEqual:@"GET"])&&[TFAIWebTools validURL:action.request.URL error:&error]&&!action.shouldPerformDownload;NSString *path=action.request.URL.path.lowercaseString;for(NSString *part in @[@"/login",@"/signin",@"/oauth/authorize",@"/sign-in"]){if(!self.manualLogin&&[path containsString:part])valid=NO;}handler(valid?WKNavigationActionPolicyAllow:WKNavigationActionPolicyCancel);if(!valid&&action.targetFrame.isMainFrame)[self finish:nil error:error?:TFAIError(480,@"只读浏览已阻止登录、表单、下载或非网页导航。")];}
- (void)webView:(WKWebView *)webView didFinishNavigation:(WKNavigation *)navigation{if(navigation!=self.activeNavigation)return;[self extract:self.serial final:NO];}
- (void)webView:(WKWebView *)webView didFailNavigation:(WKNavigation *)navigation withError:(NSError *)error{if(navigation!=self.activeNavigation)return;[self finish:nil error:TFAIError(error.code,@"网页加载失败。")];}
- (void)webView:(WKWebView *)webView didFailProvisionalNavigation:(WKNavigation *)navigation withError:(NSError *)error{if(navigation!=self.activeNavigation)return;[self finish:nil error:TFAIError(error.code,@"网页连接失败，请检查地址与网络。")];}
- (void)webViewWebContentProcessDidTerminate:(WKWebView *)webView{[self finish:nil error:TFAIError(480,@"网页进程被系统结束，请重试或使用静态web_read。")];}
- (void)extract:(NSUInteger)serial final:(BOOL)final{if(serial!=self.serial||!self.completion)return;NSString *js=@"(()=>{const root=document.querySelector('main,article,[role=main]')||document.body;return {title:document.title,url:location.href,text:(root?.innerText||'').slice(0,60000),links:Array.from(root?.querySelectorAll('a[href]')||[]).filter(a=>/^https?:/.test(a.href)).slice(0,100).map((a,i)=>({index:i,text:(a.innerText||'').slice(0,160),url:a.href})),readOnly:true,source:'untrusted-rendered-web-content'}})()";[self.webView evaluateJavaScript:js completionHandler:^(id result,NSError *error){if(serial!=self.serial||!self.completion)return;NSString *text=[result isKindOfClass:NSDictionary.class]?result[@"text"]:nil;self.attempts++;BOOL stable=text.length&&[text isEqual:self.lastText]&&self.attempts>=3;if(final||stable||self.attempts>=12){[self finish:[result isKindOfClass:NSDictionary.class]?result:nil error:error?TFAIError(480,@"网页正文提取失败。"):nil];return;}self.lastText=text;dispatch_after(dispatch_time(DISPATCH_TIME_NOW,700*NSEC_PER_MSEC),dispatch_get_main_queue(),^{[self extract:serial final:NO];});}];}
- (WKWebView *)webView:(WKWebView *)webView createWebViewWithConfiguration:(WKWebViewConfiguration *)config forNavigationAction:(WKNavigationAction *)action windowFeatures:(WKWindowFeatures *)features{return nil;}
- (void)webView:(WKWebView *)webView runJavaScriptAlertPanelWithMessage:(NSString *)message initiatedByFrame:(WKFrameInfo *)frame completionHandler:(void (^)(void))completionHandler{completionHandler();}
- (void)webView:(WKWebView *)webView runJavaScriptConfirmPanelWithMessage:(NSString *)message initiatedByFrame:(WKFrameInfo *)frame completionHandler:(void (^)(BOOL))completionHandler{completionHandler(NO);}
- (void)webView:(WKWebView *)webView runJavaScriptTextInputPanelWithPrompt:(NSString *)prompt defaultText:(NSString *)text initiatedByFrame:(WKFrameInfo *)frame completionHandler:(void (^)(NSString *))completionHandler{completionHandler(nil);}
