@end
@implementation TFAIBrowserPage
- (UIButton *)button:(NSString *)symbol title:(NSString *)title action:(SEL)action{UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem];[button setImage:[UIImage systemImageNamed:symbol] forState:UIControlStateNormal];button.accessibilityLabel=title;button.tintColor=UIColor.labelColor;[button addTarget:self action:action forControlEvents:UIControlEventTouchUpInside];[button.widthAnchor constraintEqualToConstant:44].active=YES;return button;}
- (void)viewDidLoad{[super viewDidLoad];[NSNotificationCenter.defaultCenter removeObserver:self name:@"DylixBrowserTabChanged" object:nil];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(browserChanged:) name:@"DylixBrowserTabChanged" object:nil];self.title=@"浏览器";self.navigationItem.rightBarButtonItems=@[AIBar(@"arrow.right",@"打开网页",self,@selector(openAddress)),AIBar(@"square.on.square",@"会话标签与数据",self,@selector(tabMenu))];self.view.backgroundColor=UIColor.systemBackgroundColor;self.browser=[TFAIReadOnlyBrowser browserForSession:self.sessionID];if(!self.browser){AIAlert(self,@"浏览器数量已满",@"最多保留16个会话浏览器，请先关闭不用的页面并重启应用。");return;}self.address=[UITextField new];self.address.placeholder=@"输入公开网页地址";self.address.autocapitalizationType=UITextAutocapitalizationTypeNone;self.address.autocorrectionType=UITextAutocorrectionTypeNo;self.address.clearButtonMode=UITextFieldViewModeWhileEditing;self.address.borderStyle=UITextBorderStyleRoundedRect;self.address.keyboardType=UIKeyboardTypeURL;self.address.returnKeyType=UIReturnKeyGo;self.address.delegate=self;self.address.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:self.address];self.progress=[UIProgressView new];self.progress.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:self.progress];WKWebView *web=self.browser.webView;[web removeFromSuperview];web.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:web];self.backButton=[self button:@"chevron.left" title:@"后退" action:@selector(goBack)];self.forwardButton=[self button:@"chevron.right" title:@"前进" action:@selector(goForward)];UIButton *reload=[self button:@"arrow.clockwise" title:@"刷新" action:@selector(reloadPage)];UIButton *ask=[self button:@"sparkles" title:self.onAsk?@"让 AI 阅读当前页":@"复制当前页地址" action:@selector(askAI)];UIStackView *toolbar=[[UIStackView alloc]initWithArrangedSubviews:@[self.backButton,self.forwardButton,reload,ask]];toolbar.distribution=UIStackViewDistributionEqualSpacing;toolbar.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:toolbar];[NSLayoutConstraint activateConstraints:@[[self.address.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor constant:8],[self.address.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:12],[self.address.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-12],[self.address.heightAnchor constraintEqualToConstant:42],[self.progress.topAnchor constraintEqualToAnchor:self.address.bottomAnchor constant:5],[self.progress.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[self.progress.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[web.topAnchor constraintEqualToAnchor:self.progress.bottomAnchor constant:3],[web.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[web.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[web.bottomAnchor constraintEqualToAnchor:toolbar.topAnchor constant:-4],[toolbar.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:16],[toolbar.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-16],[toolbar.bottomAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.bottomAnchor constant:-2],[toolbar.heightAnchor constraintEqualToConstant:44]]];for(NSString *key in @[@"URL",@"title",@"estimatedProgress",@"loading",@"canGoBack",@"canGoForward"])[web addObserver:self forKeyPath:key options:NSKeyValueObservingOptionNew context:NULL];[self refreshChrome];}
- (void)browserChanged:(NSNotification *)note{if([note.object isEqual:self.sessionID?:@"settings"]&&self.isViewLoaded&&self.browser&&self.browser!=[TFAIReadOnlyBrowser browserForSession:self.sessionID])[self changeBrowser];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];if(self.browser&&self.browser!=[TFAIReadOnlyBrowser browserForSession:self.sessionID])[self changeBrowser];}
- (void)changeBrowser{for(NSString *key in @[@"URL",@"title",@"estimatedProgress",@"loading",@"canGoBack",@"canGoForward"])[self.browser.webView removeObserver:self forKeyPath:key];[self.browser.webView removeFromSuperview];self.browser=nil;self.view=nil;[self loadViewIfNeeded];}
- (void)browserPrivacy{UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"本会话网页数据" message:@"默认临时数据。保存登录态使用此会话独立的 WebKit 数据存储，仅供浏览器使用；不会导出 Cookie。手动登录期间 AI 读取和交互暂停，退出后恢复只读保护。" preferredStyle:UIAlertControllerStyleActionSheet];BOOL persistent=[NSUserDefaults.standardUserDefaults boolForKey:BrowserPreference(self.sessionID)];
