 [menu addAction:[UIAlertAction actionWithTitle:self.browser.manualLogin?@"退出手动登录，恢复 AI 只读浏览":@"手动登录（停用 AI 网页工具）" style:UIAlertActionStyleDefault handler:^(id a){[TFAIReadOnlyBrowser setManualLogin:!self.browser.manualLogin session:self.sessionID];[self changeBrowser];}]];
 [menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:menu animated:YES completion:nil];}
- (void)tabMenu{UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"当前会话的浏览器标签" message:@"每会话最多8个标签。网页数据仅在本次进程保存；清理不影响其他会话。AI 不能读取原始 Cookie，表单提交和登录默认禁用。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary *tab in [TFAIReadOnlyBrowser tabsForSession:self.sessionID]){[menu addAction:[UIAlertAction actionWithTitle:[NSString stringWithFormat:@"%@%@",[tab[@"active"] boolValue]?@"✓ ":@"",tab[@"title"]] style:UIAlertActionStyleDefault handler:^(id a){[TFAIReadOnlyBrowser selectTab:tab[@"id"] session:self.sessionID];[self changeBrowser];}]];}[menu addAction:[UIAlertAction actionWithTitle:@"登录态与手动登录" style:UIAlertActionStyleDefault handler:^(id a){[self browserPrivacy];}]];[menu addAction:[UIAlertAction actionWithTitle:@"新建标签" style:UIAlertActionStyleDefault handler:^(id a){if([TFAIReadOnlyBrowser newTabForSession:self.sessionID])[self changeBrowser];else AIAlert(self,@"标签已满",@"请先关闭不用的标签。");}]];[menu addAction:[UIAlertAction actionWithTitle:@"关闭当前标签" style:UIAlertActionStyleDestructive handler:^(id a){for(NSDictionary *tab in [TFAIReadOnlyBrowser tabsForSession:self.sessionID])if([tab[@"active"] boolValue]){[TFAIReadOnlyBrowser closeTab:tab[@"id"] session:self.sessionID];break;}[self changeBrowser];}]];[menu addAction:[UIAlertAction actionWithTitle:@"清理本会话所有网页数据…" style:UIAlertActionStyleDestructive handler:^(id a){UIAlertController *confirm=[UIAlertController alertControllerWithTitle:@"关闭标签并清理网页数据？" message:@"只影响当前会话，操作不能撤销。" preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:@"清理" style:UIAlertActionStyleDestructive handler:^(id a){[TFAIReadOnlyBrowser clearSession:self.sessionID completion:^{[self changeBrowser];}];}]];[self presentViewController:confirm animated:YES completion:nil];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:menu animated:YES completion:nil];}
- (void)dealloc{[NSNotificationCenter.defaultCenter removeObserver:self];for(NSString *key in @[@"URL",@"title",@"estimatedProgress",@"loading",@"canGoBack",@"canGoForward"])[self.browser.webView removeObserver:self forKeyPath:key];}
- (void)observeValueForKeyPath:(NSString *)keyPath ofObject:(id)object change:(NSDictionary *)change context:(void *)context{if(object==self.browser.webView){[self refreshChrome];return;}[super observeValueForKeyPath:keyPath ofObject:object change:change context:context];}
- (void)refreshChrome{WKWebView *web=self.browser.webView;if(!self.address.isFirstResponder)self.address.text=web.URL.absoluteString?:@"";self.title=web.title.length?web.title:@"浏览器";self.progress.progress=(float)web.estimatedProgress;self.progress.hidden=!web.isLoading;self.backButton.enabled=web.canGoBack;self.forwardButton.enabled=web.canGoForward;}
- (BOOL)textFieldShouldReturn:(UITextField *)textField{[self openAddress];return YES;}
- (void)openAddress{[self.view endEditing:YES];NSString *value=[self.address.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!value.length)return;if(![value containsString:@"://"])value=[@"https://" stringByAppendingString:value];if(self.browser.manualLogin){NSError *error=nil;NSURL *url=[NSURL URLWithString:value];if([TFAIWebTools validURL:url error:&error])[self.browser.webView loadRequest:[NSURLRequest requestWithURL:url]];else AIAlert(self,@"网页未打开",error.localizedDescription);return;}[self.browser read:value completion:^(NSDictionary *result,NSError *error){if(error)AIAlert(self,@"网页未打开",error.localizedDescription);}];}
- (void)goBack{[self.browser.webView goBack];}
- (void)goForward{[self.browser.webView goForward];}
- (void)reloadPage{if(self.browser.webView.URL)[self.browser.webView reload];else[self openAddress];}
- (void)askAI{if([TFAIReadOnlyBrowser AIBlockedForSession:self.sessionID]){AIAlert(self,@"AI 网页工具已暂停",@"请先退出手动登录。");return;}NSString *url=self.browser.webView.URL.absoluteString;if(!url.length){AIAlert(self,@"还没有网页",@"先输入地址打开网页。");return;}if(self.onAsk)self.onAsk(url);else{UIPasteboard.generalPasteboard.string=url;AIAlert(self,@"已复制网页地址",@"在 AI 会话中粘贴地址即可让 AI 阅读。");}}
@end
UIViewController *TFAIReadOnlyBrowserController(void){return [TFAIBrowserPage new];}
UIViewController *TFAIReadOnlyBrowserControllerWithAsk(NSString *sessionID,void (^onAsk)(NSString *url)){TFAIBrowserPage *page=[TFAIBrowserPage new];page.sessionID=sessionID;page.onAsk=onAsk;return page;}
